/**
 * Loads the Go-SDK-generated fixtures.
 *
 *   vectors.json      - Opentrade/server/test/vectors.json, copied VERBATIM (19 vectors).
 *   vectors-sdk.json  - regenerated by tools/genvectors.sh from sodex-go-sdk-public
 *                       (commit in vectors-sdk.commit): Opentrade's 19 again plus
 *                       the Valuescan additions (builder codes, AddAPIKey,
 *                       AddAPIKeyWithBuilder, ApproveBuilderFee, TWAP, revocation,
 *                       Go string escaping, more decimals).
 */
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { hexToBytes } from '../src/eip712.ts';
import type { PerpsSymbol } from '../src/types/rest.ts';

const here = dirname(fileURLToPath(import.meta.url));

export interface ExchangeVector {
  name: string;
  engine: string;
  actionType: string;
  nonce: number;
  payloadJSON: string;
  payloadHash: string;
  bodyJSON: string;
  signature: string;
}

export interface UserVector {
  name: string;
  primaryType: string;
  domainChainID: number;
  messageChainID: number;
  nonce: number;
  message: Record<string, unknown>;
  structHash: string;
  digest: string;
  signature: string;
  source: string;
}

export interface VectorFile {
  privateKey: string;
  address: string;
  chainID: number;
  domainSpot: string;
  domainPerps: string;
  domainUniv: string;
  sigTypeExch: number;
  sigTypeUniv: number;
  decimals: Record<string, string>;
  vectors: ExchangeVector[];
}

export interface SdkVectorFile extends VectorFile {
  userVectors: UserVector[];
  decimalsExtra: Record<string, string>;
  goJSONStrings: Record<string, string>;
  domainUnivNet: string;
  domainPerpsMainnet: string;
  domainSpotMainnet: string;
  domainUnivMainnet: string;
  domainUnivArbitrum: string;
  permissionMasks: Record<string, number>;
}

const load = <T>(name: string): T => JSON.parse(readFileSync(join(here, name), 'utf8')) as T;

export const V = load<VectorFile>('vectors.json');
export const S = load<SdkVectorFile>('vectors-sdk.json');
export const SDK_COMMIT = readFileSync(join(here, 'vectors-sdk.commit'), 'utf8').trim();

/** The SDK's published throwaway test key. NEVER used for anything real. */
export const PK = hexToBytes(V.privateKey);

export function vec(file: VectorFile, name: string): ExchangeVector {
  const v = file.vectors.find((x) => x.name === name);
  if (!v) throw new Error(`missing vector ${name}`);
  return v;
}

export function uvec(name: string): UserVector {
  const v = S.userVectors.find((x) => x.name === name);
  if (!v) throw new Error(`missing user vector ${name}`);
  return v;
}

export const srcDir = join(here, '..', 'src');

